["url"] = "https://wago.io/mA-zQQEsD/4",
["PlaterCore"] = 1,
["Name"] = "PVP/PVE School Lock Buff Special",
},
{
["OptionsValues"] = {
["sparkWidth"] = 12,
["specialColorsEnabled"] = false,
