["UpdateCode"] = "function (self, unitId, unitFrame, envTable, scriptTable)\n    Plater.SetNameplateColor (unitFrame, scriptTable.config.npColor)\n    \n    local timeLeft = envTable._RemainingTime\n    \n    if (timeLeft < envTable._Duration*0.3) then      \n        if scriptTable.config.isGlowEnabled then\n            envTable.pandemicGlow:Show()\n        end\n        if scriptTable.config.isFlashEnabled then\n            envTable.fsFlash:Play()\n        end\n        if scriptTable.config.isTimerColorEnabled then\n            Plater:SetFontColor (self.Cooldown.Timer,scriptTable.config.timerColor)\n        end\n    else\n        if scriptTable.config.isGlowEnabled then\n            envTable.pandemicGlow:Hide()\n        end\n        if scriptTable.config.isFlashEnabled then\n            envTable.fsFlash:Stop()\n        end \n        if scriptTable.config.isTimerColorEnabled then\n            Plater:SetFontColor (self.Cooldown.Timer, Plater.db.profile.aura_timer_text_color)\n        end\n    end\n    \n    self:SetScale(scriptTable.config.fsScale)\n    \n    \n    local r, g, b, a = DetailsFramework:ParseColors (scriptTable.config.borderColor)\n    self:SetBackdropBorderColor (r, g, b, a)\n    \nend",
