{
["ConstructorCode"] = "function(self, unitId, unitframe, envTable)\n    \n    envTable.virulentplague = envTable.virulentplague or Plater.CreateIconGlow (self)\n    --envTable.virulentplague:Show() --envTable.virulentplague:Hide()\n    \n    \n    \nend\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n",
["OnHideCode"] = "function (self, unitId, unitFrame, envTable)\n    \n    envTable.virulentplague:Hide()\n    \n    \nend\n\n\n",
["Temp_OnShowCode"] = "function (self, unitId, unitFrame, envTable)\n    \n    \n    \nend\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n",
["ScriptType"] = 1,
["UpdateCode"] = "function (self, unitId, unitFrame, envTable)\n    \n    for i=1,40 do\n        local name, _, _, debuffType, duration, expirationTime, unitCaster, isStealable, nameplateShowPersonal, spellId, canApplyAura, isBossDebuff, nameplateShowAll, timeMod, value1, value2, value3 = UnitDebuff(unitId,i, \"player\")\n        \n        if name == \"Virulent Plague\" then\n            local corruTimer = expirationTime - GetTime()\n            if corruTimer < 5 then\n                envTable.virulentplague:Show()\n            else\n                envTable.virulentplague:Hide()\n            end\n            \n            break\n        end\n    end\n    \nend\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n",
