["Hooks"] = {
["Constructor"] = "function (self, unitId, unitFrame, envTable, modTable)\n    --insert code here\n    \nend",
["Nameplate Updated"] = "function (self, unitId, unitFrame, envTable, modTable)\n    \n    self.ThrottleUpdate = 0.016\n    \n    -- function to get the stack count of a specific aura\n    local function GetDebuffStackCount(unitId, spellId)\n        for i = 1, 40 do\n            local name, _, count, _, _, _, _, _, _, spellID = UnitAura(unitId, i, \"HARMFUL\")\n            if not name then break end -- no more auras\n            if spellID == spellId then\n                return count\n            end\n        end\n        return 0 -- return 0 if the aura is not found\n    end\n    \n    -- check if the unit has Razor Ice debuff and get its stack count\n    local hasRazorIce = Plater.NameplateHasAura(unitFrame, 51714)\n    local razorIceStackCount = GetDebuffStackCount(unitId, 51714)\n    \n    -- get the player's specialization ID\n    local specId = GetSpecializationInfo(GetSpecialization())\n    \n    -- if the player is a Frost Death Knight (spec ID 251)\n    if specId == 251 then\n        if not hasRazorIce then\n            Plater.RefreshNameplateColor(unitFrame)\n        else\n            if razorIceStackCount == 5 then\n                Plater.SetNameplateColor(unitFrame, modTable.config.razorIceColor)\n            else\n                Plater.RefreshNameplateColor(unitFrame)\n            end\n        end\n    end\nend",
},
